import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Objects;

class CustomSet<T> {
    private final List<T> elements;

    CustomSet() {
        this.elements = new ArrayList<>();
    }

    CustomSet(Collection<T> data) {
        this.elements = new ArrayList<>();
        for (T element : data) {
            if (!contains(element)) {
                elements.add(element);
            }
        }
    }

    boolean isEmpty() {
        return elements.isEmpty();
    }

    boolean contains(T element) {
        return elements.contains(element);
    }

    boolean isDisjoint(CustomSet<T> other) {
        for (T element : elements) {
            if (other.contains(element)) {
                return false;
            }
        }
        return true;
    }

    boolean add(T element) {
        if (contains(element)) {
            return false;
        }
        elements.add(element);
        return true;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof CustomSet)) {
            return false;
        }
        CustomSet<?> other = (CustomSet<?>) obj;
        return elements.equals(other.elements);
    }

    @Override
    public int hashCode() {
        return Objects.hash(elements);
    }

    CustomSet<T> getIntersection(CustomSet<T> other) {
        List<T> result = new ArrayList<>();
        for (T element : elements) {
            if (other.contains(element)) {
                result.add(element);
            }
        }
        return new CustomSet<>(result);
    }

    CustomSet<T> getUnion(CustomSet<T> other) {
        List<T> result = new ArrayList<>(elements);
        for (T element : other.elements) {
            if (!result.contains(element)) {
                result.add(element);
            }
        }
        return new CustomSet<>(result);
    }

    CustomSet<T> getDifference(CustomSet<T> other) {
        List<T> result = new ArrayList<>();
        for (T element : elements) {
            if (!other.contains(element)) {
                result.add(element);
            }
        }
        return new CustomSet<>(result);
    }

    boolean isSubset(CustomSet<T> other) {
        for (T element : elements) {
            if (!other.contains(element)) {
                return false;
            }
        }
        return true;
    }
}

